function setDeveloperMode(enabled){
 S.dev=!!enabled;board.sweeps=S.dev?1:0;board.quakes=S.dev?1:0;save();
}
function testDevPower(kind){
 if(!S.dev||sweepTime>0||catquakeTime>0||['won','lost'].includes(board.status))return false;
 if(kind==='sweep'){board.sweeps=1;return board.status==='ready'?previewPawSweep():usePawSweep();}
 if(kind==='quake'){board.quakes=1;return useCatquake();}return false;
}
function openSettings() {
